def solve(haystack, needle):
    if len(needle) > len(haystack):
        return -1

    base = 31
    mod = 10**9 + 9

    def compute_hash(s):
        hash_val = 0
        for c in s:
            hash_val = (hash_val * base + ord(c)) % mod
        return hash_val

    def get_prefix_hash(s):
        prefix = [0] * (len(s) + 1)
        for i in range(len(s)):
            prefix[i+1] = (prefix[i] * base + ord(s[i])) % mod
        return prefix

    prefix = get_prefix_hash(haystack)
    prefix_needle = get_prefix_hash(needle)

    power = [1] * (len(haystack) + 1)
    for i in range(1, len(haystack) + 1):
        power[i] = (power[i-1] * base) % mod

    len_needle = len(needle)
    len_haystack = len(haystack)

    for i in range(len_haystack - len_needle + 1):
        current_hash = (prefix[i + len_needle] - prefix[i] * power[len_needle]) % mod
        if current_hash == prefix_needle[len_needle]:
            return i

    return -1
