            # Remove the leftmost character and add the next character
            current_hash = (current_hash - ord(haystack[i]) * power[len(needle)-1] % mod + mod) % mod
            current_hash = (current_hash * base + ord(haystack[i + len(needle)])) % mod

    return -1
