def solve(haystack, needle):
    if len(needle) > len(haystack):
        return -1

    def helper1(s):
        n = len(s)
        z = [0] * n
        l,.r = 0, 0
        for i in range(1, n):
            if i > .r:
                l = .r = i
                while .r < n and s[.r - l] == s[.r]:
                    .r += 1
                z[i] = .r - l
                .r -= 1
            else:
                k = i - l
                if z[k] < .r - i + 1:
                    z[i] = z[k]
                else:
                    l = i
                    while .r < n and s[.r - l] == s[.r]:
                        .r += 1
                    z[i] = .r - l
                    .r -= 1
        z[0] = n
        return z

    combined = needle + '#' + haystack
    z = helper1(combined)
    for i in range(len(needle) + 1, len(combined)):
        if z[i] >= len(needle):
            return i - len(needle) - 1
    return -1
