def solve(haystack, needle):
    if len(needle) > len(haystack):
        return -1

    last_occurrence = dict()
    for i in range(len(needle)):
        last_occurrence[needle[i]] = i

    i = 0
    while i <= len(haystack) - len(needle):
        j = len(needle) - 1
        while j >= 0 and haystack[i + j] == needle[j]:
            j -= 1
        if j == -1:
            return i
        else:
            i += max(1, j - last_occurrence.setdefault(haystack[i + j], -1))

    return -1
