    right = len(nums) - 1

    while left < right:
        mid = (left + right) //
        count = 0
        for num in nums:
            if num <= mid:
                count += 1
        if count > mid:
            right = mid
        elif count < mid:
            left = mid + 1
        # if count == mid, it's not possible in this problem setup
    return left
```

